#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAP 1024
#define MAXBLK 210

static long long pool[205000];
static int poolTop = 0;

typedef struct { long long *ptr; int size; } Block;
static Block blocks[MAXBLK];
static int nblocks = 0;

static char inbuf[1 << 22];
static int inPos = 0, inLen = 0;

static inline void readLL(long long *out) {
    while (inPos < inLen && (inbuf[inPos] < '0' || inbuf[inPos] > '9') && inbuf[inPos] != '-') inPos++;
    int neg = 0;
    if (inPos < inLen && inbuf[inPos] == '-') { neg = 1; inPos++; }
    long long v = 0;
    while (inPos < inLen && inbuf[inPos] >= '0' && inbuf[inPos] <= '9') {
        v = v * 10 + (inbuf[inPos] - '0');
        inPos++;
    }
    *out = neg ? -v : v;
}

static inline int upperBound(const long long *a, int n, long long x) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (a[mid] <= x) lo = mid + 1; else hi = mid;
    }
    return lo;
}

static int rankLE(long long x) {
    int cnt = 0;
    for (int i = 0; i < nblocks; i++) {
        Block *b = &blocks[i];
        if (b->ptr[b->size - 1] <= x) {
            cnt += b->size;
        } else {
            cnt += upperBound(b->ptr, b->size, x);
            break;
        }
    }
    return cnt;
}

static void insertVal(long long x) {
    if (nblocks == 0) {
        blocks[0].ptr = pool;
        poolTop = CAP;
        blocks[0].ptr[0] = x;
        blocks[0].size = 1;
        nblocks = 1;
        return;
    }
    int bi = 0;
    while (bi < nblocks - 1 && blocks[bi].ptr[blocks[bi].size - 1] < x) bi++;
    Block *b = &blocks[bi];
    if (b->size == CAP) {
        long long *np = pool + poolTop;
        poolTop += CAP;
        int half = CAP / 2;
        memcpy(np, b->ptr + half, (size_t)(CAP - half) * sizeof(long long));
        Block nb;
        nb.ptr = np;
        nb.size = CAP - half;
        b->size = half;
        memmove(&blocks[bi + 2], &blocks[bi + 1], (size_t)(nblocks - bi - 1) * sizeof(Block));
        blocks[bi + 1] = nb;
        nblocks++;
        b = &blocks[bi];
        if (x > b->ptr[b->size - 1]) b = &blocks[bi + 1];
    }
    int pos = upperBound(b->ptr, b->size, x);
    memmove(b->ptr + pos + 1, b->ptr + pos, (size_t)(b->size - pos) * sizeof(long long));
    b->ptr[pos] = x;
    b->size++;
}

static char out[1 << 22];

int main(void) {
    inLen = (int)fread(inbuf, 1, sizeof(inbuf), stdin);
    long long n;
    readLL(&n);
    long long prevP = 0;
    int outPos = 0;
    for (long long k = 0; k < n; k++) {
        long long X, Y;
        readLL(&X);
        readLL(&Y);
        long long xr = X + prevP;
        long long yr = Y + prevP;
        long long d = xr * xr + yr * yr;
        long long p = rankLE(d);
        insertVal(d);
        prevP = p;
        if (p == 0) {
            out[outPos++] = '0';
        } else {
            char tmp[24];
            int t = 0;
            long long v = p;
            while (v > 0) { tmp[t++] = (char)('0' + (v % 10)); v /= 10; }
            while (t > 0) out[outPos++] = tmp[--t];
        }
        out[outPos++] = '\n';
    }
    fwrite(out, 1, (size_t)outPos, stdout);
    return 0;
}
